package com.orderflow.notification.messaging;import com.fasterxml.jackson.databind.ObjectMapper;import com.orderflow.events.*;import com.orderflow.notification.domain.NotificationType;import com.orderflow.notification.service.NotificationWorkflowService;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.messaging.handler.annotation.Header;import org.springframework.stereotype.Component;
@Component public class DomainEventListener{private final ObjectMapper m;private final NotificationWorkflowService w;public DomainEventListener(ObjectMapper m,NotificationWorkflowService w){this.m=m;this.w=w;}@KafkaListener(topics={"${app.kafka.topics.payment-events}","${app.kafka.topics.delivery-events}"},groupId="notification-service-domain-events-v1")public void consume(String payload,@Header("eventType")String name)throws Exception{switch(EventType.valueOf(name)){case PAYMENT_SUCCEEDED->{var e=m.readValue(payload,PaymentSucceededEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.PAYMENT_SUCCEEDED);}case PAYMENT_FAILED->{var e=m.readValue(payload,PaymentFailedEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.PAYMENT_FAILED);}case PAYMENT_REFUNDED->{var e=m.readValue(payload,PaymentRefundedEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.ORDER_REFUNDED);}case DELIVERY_ASSIGNED->{var e=m.readValue(payload,DeliveryAssignedEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.DELIVERY_ASSIGNED);}case DELIVERY_PICKED_UP->{var e=m.readValue(payload,DeliveryPickedUpEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.DELIVERY_PICKED_UP);}case DELIVERY_OUT_FOR_DELIVERY->{var e=m.readValue(payload,DeliveryOutForDeliveryEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.DELIVERY_OUT_FOR_DELIVERY);}case DELIVERY_DELIVERED->{var e=m.readValue(payload,DeliveryDeliveredEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.DELIVERY_DELIVERED);}case DELIVERY_FAILED->{var e=m.readValue(payload,DeliveryFailedEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.DELIVERY_FAILED);}case DELIVERY_CANCELLED->{var e=m.readValue(payload,DeliveryCancelledEvent.class);w.process(e.metadata(),e.customerId(),NotificationType.DELIVERY_CANCELLED);}default->{ }}}}
